import 'package:flutter/material.dart';

class QuantityStepper extends StatelessWidget {
  QuantityStepper({super.key});

  int quantity = 1; // warning: must_be_immutable

  @override
  Widget build(BuildContext context) {
    return Row(children: [
      Text('$quantity'),
      IconButton(
        icon: const Icon(Icons.add),
        onPressed: () => quantity++, // the field changes, the screen doesn't
      ),
    ]);
  }
}

import 'package:flutter/material.dart';

class QuantityStepper extends StatefulWidget {
  const QuantityStepper({super.key});

  @override
  State<QuantityStepper> createState() => _QuantityStepperState();
}

class _QuantityStepperState extends State<QuantityStepper> {
  int quantity = 1; // lives in the State, which the element keeps

  @override
  Widget build(BuildContext context) {
    return Row(children: [
      Text('$quantity'),
      IconButton(
        icon: const Icon(Icons.add),
        onPressed: () => setState(() => quantity++),
      ),
    ]);
  }
}
